-- CREATE PROCEDURE clauses
-- https://docs.snowflake.com/en/sql-reference/sql/create-procedure

CREATE OR REPLACE TEMPORARY PROCEDURE p()
RETURNS VARCHAR
LANGUAGE JAVASCRIPT
AS 'return 1;';

CREATE TEMP PROCEDURE p()
RETURNS VARCHAR
LANGUAGE JAVASCRIPT
AS 'return 1;';

CREATE PROCEDURE p(a IN INT, b OUT VARCHAR)
RETURNS INT
LANGUAGE SQL
AS
BEGIN
    RETURN a;
END;

CREATE PROCEDURE p(a INPUT INT, b OUTPUT VARCHAR)
RETURNS INT
LANGUAGE SQL
AS
BEGIN
    RETURN a;
END;

CREATE PROCEDURE p()
RETURNS INT
LANGUAGE SQL
EXECUTE AS RESTRICTED CALLER
AS
BEGIN
    RETURN 1;
END;

CREATE PROCEDURE p()
RETURNS VARCHAR NULL
LANGUAGE PYTHON
RUNTIME_VERSION = '3.11'
PACKAGES = ('snowflake-snowpark-python')
HANDLER = 'run'
AS 'def run(session): return 1';

CREATE PROCEDURE p()
RETURNS VARCHAR
LANGUAGE PYTHON
RUNTIME_VERSION = '3.11'
ARTIFACT_REPOSITORY = snowflake.snowpark.pypi_shared_repository
PACKAGES = ('urllib3')
HANDLER = 'run'
AS 'def run(session): return 1';

-- Anonymous procedure
WITH myproc AS PROCEDURE (x INT)
RETURNS INT
LANGUAGE SQL
AS $$
BEGIN
    RETURN x;
END;
$$
CALL myproc(1);

WITH myproc AS PROCEDURE (x INT)
RETURNS INT
LANGUAGE SQL
EXECUTE AS CALLER
AS $$
BEGIN
    RETURN x;
END;
$$
CALL myproc(1);
